"use client";

import { useState } from "react";
import AIAvatar from "./AIAvatar";
import ChatInput from "./ChatInput";

export default function Chat() {
  const [messages, setMessages] = useState<
    {
      id: number;
      role: "user" | "assistant";
      content: string;
    }[]
  >([]);

  function sendMessage(message: string) {
    if (!message.trim()) return;

    const userMessage = {
      id: Date.now(),
      role: "user" as const,
      content: message,
    };

    setMessages((current) => [...current, userMessage]);

    setTimeout(() => {
      setMessages((current) => [
        ...current,
        {
          id: Date.now(),
          role: "assistant",
          content:
            "Entendi. Ainda estou sendo configurada, mas em breve poderei processar essa solicitação.",
        },
      ]);
    }, 500);
  }

  return (
    <div className="flex h-full flex-col">
      {/* Área das mensagens */}
      <div className="flex-1 overflow-y-auto">
        {messages.length === 0 ? (
          <div className="flex h-full flex-col items-center justify-center px-6">
            <AIAvatar size="lg" />

            <h1 className="mt-6 text-2xl font-semibold">Como posso ajudar?</h1>

            <p className="mt-2 max-w-md text-center text-sm leading-6 text-zinc-500">
              Converse comigo, analise seu currículo, pesquise informações ou
              consulte seu computador.
            </p>

            <div className="mt-8 grid max-w-xl grid-cols-2 gap-3">
              {[
                "Analise meu currículo",
                "Como está meu PC?",
                "Pesquise sobre IA",
                "Me ajude a programar",
              ].map((suggestion) => (
                <button
                  key={suggestion}
                  onClick={() => sendMessage(suggestion)}
                  className="rounded-xl border border-white/[0.08] bg-white/[0.025] px-4 py-3 text-left text-xs text-zinc-400 transition hover:border-white/15 hover:bg-white/[0.05] hover:text-white"
                >
                  {suggestion}
                </button>
              ))}
            </div>
          </div>
        ) : (
          <div className="mx-auto max-w-3xl space-y-6 px-6 py-8">
            {messages.map((message) => (
              <div
                key={message.id}
                className={`flex gap-3 ${
                  message.role === "user" ? "justify-end" : "justify-start"
                }`}
              >
                {message.role === "assistant" && <AIAvatar size="sm" />}

                <div
                  className={`max-w-[75%] rounded-2xl px-4 py-3 text-sm leading-6 ${
                    message.role === "user"
                      ? "bg-white text-black"
                      : "border border-white/[0.08] bg-white/[0.03] text-zinc-300"
                  }`}
                >
                  {message.content}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Input */}
      <ChatInput onSend={sendMessage} />
    </div>
  );
}
